'use strict';
const V8={compare:false,routeView:null,signature:'',map:null};
function v8Weather(){const w=vWeatherData(),history=V2.mode==='history';return `<section class="v8weather"><div class="v8weathermain"><div class="v8weathericon">${icon('rain',27)}</div><div><b>天气与趋势</b><small>${history?'历史资料模式':'模型天气参考 · 非官方预警'}</small></div><div class="v8weathernumbers"><span><b>${!history&&w.temperature!=null?w.temperature+'°C':'—'}</b><small>气温</small></span><span><b>${!history&&w.rain!=null?w.rain+' mm':'—'}</b><small>${V2.departure==='planned'?'小时降水':w.interval?'近'+Math.round(w.interval/60)+'分钟降水':'降水量'}</small></span><span><b>${!history&&w.wind!=null?w.wind+' m/s':'—'}</b><small>风速</small></span></div><label class="v8location"><span>天气地点</span><input id="v5-weather-place" value="${esc(V5.weatherPlace)}" placeholder="地点或纬度,经度"></label><button data-v5="weather">刷新天气</button></div><div class="v8weatherfoot"><span>${V2.weather?.place?esc(V2.weather.place)+' · ':''}${w.time&&!history?'数据时刻 '+esc(dateText(w.time)):'尚无可用时段数据'} · 现场水深未知</span><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">官方天气 ↗</a></div><details class="v8weatherdetails"><summary>展开24小时趋势与数据表 ${icon('clock',13)}</summary>${v5Trend()}<p class="muted">台风实时路径与动态官方预警尚未接入。道路积水受地形、汇水和排水能力共同影响，降雨量与水深是不同指标。</p><button data-v5="report" data-value="天气趋势">导出天气报告</button></details></section>`}
function v8Form(){return `<section class="v8journey"><div class="v8sectionhead"><span class="v8step">1</span><h2>规划行程</h2><span class="tag gray">${V2.mode==='history'?'历史':'现在'}</span></div><div class="v8timecontrols">${vTimeControls()}</div><form id="v2-journey" class="v8journeyform"><div class="v8routechain"><div class="field"><label for="v2-origin">出发点</label><input id="v2-origin" name="origin" value="${esc(V2.origin)}" placeholder="小区、街道或详细地址" required></div>${V2.vias.map((v,i)=>`<div class="field v8via"><label>途经点 ${i+1}</label><div><input name="via-${i}" data-via="${i}" value="${esc(v)}" placeholder="途经地点"><button type="button" data-v2="remove-via" data-value="${i}" aria-label="删除途经点">×</button></div></div>`).join('')}<div class="field"><label for="v2-destination">目的地</label><input id="v2-destination" name="destination" value="${esc(V2.destination)}" placeholder="医院、公司或详细地址" required></div></div><div class="v8smallactions"><button type="button" data-v2="add-via">＋途经点</button>${V5.addresses.slice(0,3).map((a,i)=>`<button type="button" data-v5="address" data-value="${i}">${esc(a.label)}</button>`).join('')}<button type="button" data-v5="add-address">＋快捷地址</button></div><div class="v8modes">${['公共交通','步行','驾车'].map(t=>`<button type="button" data-v2="transport" data-value="${t}" class="${V2.transport===t?'active':''}">${icon(t==='步行'?'map':'route',16)} ${t}</button>`).join('')}</div><div class="v8round"><label><input id="v5-round" type="checkbox" ${V5.round?'checked':''}> 需要返回</label>${V5.round?`<div class="field"><label>目的地停留（分钟）</label><input id="v5-stay" type="number" min="0" max="1440" value="${V5.stay}"></div><div class="field"><label>返程时间（可选）</label><input id="v5-return" type="datetime-local" value="${esc(V5.returnAt)}"></div>`:''}<details><summary>出行目的与地点说明</summary><div class="field"><label>出行目的</label><select id="v5-purpose">${['日常出行','就医','上班','上学','其他'].map(t=>`<option ${V5.purpose===t?'selected':''}>${t}</option>`).join('')}</select></div><p>可自由填写地点；当前坐标自动匹配覆盖公开站点，其他地址可输入纬度,经度。完整地址搜索待接入。</p></details></div><button class="primary v8querybutton" type="submit" ${V2.loading?'disabled':''}>${V2.loading?'正在查询…':'查询并添加出行方案'} ${icon('search',15)}</button>${V2.error?`<p class="notice warn">${esc(V2.error)}</p>`:''}</form></section>`}
function v8Plan(p,i){return `<article class="v8plan ${p.id===V2.focus?'focused':''}"><div class="row"><button class="v8planname" data-v2="focus" data-value="${p.id}"><i style="background:${vRouteColor(p)}"></i>方案 ${i+1} · ${esc(p.transport)}</button><button class="v8delete" data-v2="delete-plan" data-value="${p.id}" aria-label="删除方案${i+1}">×</button></div><div class="v8plandetail"><b>${p.duration!=null?Math.ceil(p.duration/60)+'分钟':'时长待取得'}</b><span>${p.distance!=null?(p.distance/1000).toFixed(1)+' km':'距离未知'}</span></div><p>${esc(p.origin)} → ${esc(p.destination)}</p><div class="row"><span class="tag ${v5Risk(p)==='风险未知'?'gray':'orange'}">${v5Risk(p)}</span><small>${p.mode==='history'?'历史地点连线':'参考方案 · 非实时路况'}</small></div></article>`}
function v8Summary(){const p=vFocus(),risk=vRisks(p),f=vFeedback(p),e=vRelated(p);return `<section class="v8summary"><div class="v8sectionhead"><span class="v8step">3</span><h2>风险与出行判断</h2><span class="tag gray">规则关联 · AI待接入</span></div><div class="v8evidence"><button data-v8="evidence" data-value="official"><span>官方关联</span><b>${risk.length}<small> 条</small></b><em>长期隐患资料 ↗</em></button><button data-v8="evidence" data-value="feedback"><span>用户线索</span><b>${f.length}<small> 条</small></b><em>本地记录 · 待核验 ↗</em></button><button data-v8="evidence" data-value="events"><span>相关公告</span><b>${e.length}<small> 条</small></b><em>适用时间需核对 ↗</em></button></div><div class="v8conclusion"><span class="v8conclusionicon">${icon('layers',19)}</span><div><b>${p?v5Risk(p):'先查询行程，再查看风险依据'}</b><p>${risk.length?'已有地名与长期隐患资料关联，请核对具体位置和适用时段。':'沿线资料覆盖不完整，不能依据未匹配记录判断路线安全。'}</p><small>路线不包含实时洪涝、封路和拥堵；危险概率未取得校准模型。</small></div></div>${V5.round?`<details open class="v8analysis"><summary>去程与返程分析</summary>${v5Base.advice? v8RoundPanel(p):''}</details>`:''}<details class="v8analysis"><summary>查看完整关联资料与预测状态</summary>${vHazards()}${vRecommendation()}</details><div class="v8summaryfoot"><span>资料更新时间：待核验</span><button data-v5="report" data-value="风险与往返分析">导出分析报告 ↗</button></div></section>`}
function v8RoundPanel(p){const rt=v5RoundData(p);return `<div class="v8roundtable"><div><span>去程</span><b>${esc(dateText(rt.depart))}</b><small>${esc(v5RainAt(rt.depart))}</small></div><div><span>返程</span><b>${rt.returnTime?esc(dateText(rt.returnTime)):'请指定返程时间'}</b><small>${esc(v5RainAt(rt.returnTime))}</small></div></div><p>返程需单独查询路径，不能沿用去程风险。</p><button data-v5="return-plan">反向查询返程 →</button>`}
vDashboard=function(){const focus=vFocus(),selected=V2.plans.filter(p=>V2.selected.includes(p.id));return `<header class="v8pageintro"><div><span class="v8eyebrow">深圳 · 罗湖</span><h1>每一趟出行，多一份依据。</h1><p>填行程、看路径、核对风险，再决定如何出发。</p></div><div class="v8introactions"><button data-v2="share">${icon('route',15)} 分享查询</button><button data-v2="export">${icon('layers',15)} 生成报告</button></div></header>${v8Weather()}<div class="v8workspace"><aside class="v8planner">${v8Form()}<section class="v8options"><div class="v8sectionhead"><span class="v8step">2</span><h2>出行方案</h2><small>${V2.plans.length} 条</small></div>${V2.plans.length?V2.plans.map(v8Plan).join(''):`<div class="v8empty"><div>${icon('route',32)}</div><b>你的下一趟行程</b><p>填写地点后查询方案。已匹配坐标的驾车行程可尝试公开路线服务。</p><small>公共交通使用有限参考走廊，步行使用专用公开路由。</small></div>`}<button class="v8comparebutton" data-v8="compare" ${V2.plans.length<2?'disabled':''}>${V8.compare?'收起方案比较':'比较多个方案'} ${V2.plans.length>=2?'↗':''}</button></section></aside><div class="v8mapcolumn"><section class="v8mapsection"><div class="v8mapheading"><div><span class="v8eyebrow">${V8.compare?'多方案路径':'当前方案位置'}</span><h2>${focus?v19MapTitle(focus):'深圳罗湖 · 出行地图'}</h2></div><span class="tag gray">${V2.mode==='history'?'历史地点连线':'路线参考'}</span></div><div id="v8-route-map" aria-label="当前出行路径地图"></div><div class="v8mapoverlay"><i style="background:#159b8e"></i> 青绿：参考时长较短 · 红色区段：停运影响 · 均不代表灾时可通行</div><div id="v8-map-status" class="v8mapstatus" role="status">正在加载地图底图…</div><div class="v8mapcaption"><span>曲线：道路／轨道参考 · 未取得路径时不连线</span><a href="https://www.openstreetmap.org/#map=13/22.555/114.135" target="_blank" rel="noopener">打开底图 ↗</a></div></section>${V8.compare?`<section class="v8comparison"><div class="row"><h2>方案比较</h2><span>${selected.length} 条已选择</span></div>${v8Compare()}</section>`:''}${v8Summary()}</div></div><details class="v8sourcefold"><summary>${icon('layers',15)} 数据来源与适用范围 <span>官方链接 · 模型天气 · 路线服务</span></summary>${v5Sources()}</details>`};
function v8DropMap(){if(V8.map){const c=V8.map.getCenter();V8.routeView={lat:c.lat,lon:c.lng,zoom:V8.map.getZoom()};V8.map.remove();V8.map=null}}
function v8MountRouteMap(){const el=document.getElementById('v8-route-map');if(!el||V3.role!=='user'||V2.page!=='dashboard')return;const status=document.getElementById('v8-map-status'),L=window.L;if(!L){if(status)status.textContent='地图暂未加载，可使用“打开底图”链接。';return}try{const plans=typeof v11MapPlans==='function'?v11MapPlans():(V8.compare?V2.plans.filter(p=>V2.selected.includes(p.id)):vFocus()?[vFocus()]:[]),sig=plans.map(p=>p.id).join(',');V8.map=L.map(el,{scrollWheelZoom:false});V8.map.setView(V8.routeView?[V8.routeView.lat,V8.routeView.lon]:[22.555,114.135],V8.routeView?.zoom||13);let loaded=0;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',updateWhenIdle:true});tiles.on('tileload',()=>{loaded++;if(status)status.textContent='地图可拖动、缩放；路线及坐标未实地核验。'});tiles.on('tileerror',()=>{if(!loaded&&status)status.textContent='底图加载失败，请刷新或使用地图链接。'});tiles.addTo(V8.map);const bounds=[];plans.forEach((p,i)=>{const geo=(V2.mode==='now'||p.geometryBasis==='current-reference')&&p.geometry,coords=geo?.coordinates?.map(c=>[c[1],c[0]])||p.coords?.map(c=>[c.lat,c.lon])||[];bounds.push(...coords);if(p.segments?.length)p.segments.forEach(g=>L.polyline(g.coordinates.map(c=>[c[1],c[0]]),{color:g.closed?'#c95454':vRouteColor(p),weight:5,opacity:.85}).addTo(V8.map));else if(geo&&coords.length>1)L.polyline(coords,{color:vRouteColor(p),weight:5,opacity:.85}).addTo(V8.map);(typeof v11Markers==='function'?v11Markers(p):coords.map((c,n)=>({lat:c[0],lon:c[1],label:n===0?p.origin:n===coords.length-1?p.destination:'途经点'}))).forEach(c=>{bounds.push([c.lat,c.lon]);L.circleMarker([c.lat,c.lon],{radius:7,color:'#fff',weight:2,fillColor:vRouteColor(p),fillOpacity:1}).bindTooltip(esc(c.label),{permanent:true,direction:'top',className:'v11-map-label'}).addTo(V8.map)})});D.stations.forEach(s=>{const risk=v6Risk(s);L.circleMarker([s.lat,s.lon],{radius:4,color:'#fff',weight:1,fillColor:risk.color,fillOpacity:.8,bubblingMouseEvents:false}).bindTooltip(esc(s.name)+' · '+risk.text).on('click',()=>{V5.place=s.name;V2.page='map';vRender()}).addTo(V8.map)});if(bounds.length&&sig!==V8.signature){V8.map.fitBounds(bounds,{padding:[40,40],maxZoom:16});V8.signature=sig}V8.map.invalidateSize()}catch{if(status)status.textContent='地图初始化未完成，请刷新或打开底图链接。'}}
const v8RenderBase=vRender;vRender=function(){v8DropMap();v8RenderBase();const shell=document.querySelector('.shell');shell?.classList?.add('v8shell');v8MountRouteMap()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v8]');if(!b)return;vDraft();if(b.dataset.v8==='compare'){V8.compare=!V8.compare;vRender()}if(b.dataset.v8==='evidence'){const p=vFocus(),k=b.dataset.value;let body;if(k==='official'){const r=vRisks(p);body=r.map(x=>`<div class="listitem"><b>${esc(x.street)}</b><p>${esc(x.risk_description)}</p>${vSource(x)}</div>`).join('')||'<p>暂无明确地名匹配，沿线覆盖不完整，不代表无风险。</p>'}else if(k==='feedback')body=vFeedback(p).map(f=>`<div class="listitem"><b>${esc(f.place)}</b><p>${esc(f.content)}</p>${vPhoto(f)}${v3FeedbackProgress(f)}</div>`).join('')||'<p>暂无本地关联反馈；没有共享用户后端。</p>';else body=vRelated(p).map(x=>`<div class="listitem"><b>${esc(x.category)}</b><p>${esc(x.summary)}</p>${vEventSource(x)}</div>`).join('')||'<p>暂无该模式下明确匹配的公告，当前状态仍待核验。</p>';vDialog(k==='official'?'官方关联依据':k==='feedback'?'用户线索':'相关公告',body)}});
vRender();
function v8Compare(){const ps=V2.plans.filter(p=>V2.selected.includes(p.id));return `<div class="v8comparechoices">${V2.plans.map((p,i)=>`<label><input type="checkbox" data-plan="${p.id}" ${V2.selected.includes(p.id)?'checked':''}><i style="background:${vRouteColor(p)}"></i>方案${i+1} · ${esc(p.transport)}</label>`).join('')}</div>${ps.length>=2?`<div class="tablewrap"><table><thead><tr><th>比较项目</th>${ps.map(p=>`<th>${esc(p.origin)} → ${esc(p.destination)}</th>`).join('')}</tr></thead><tbody>${[['交通方式',p=>p.transport],['参考时长',p=>p.duration!=null?Math.ceil(p.duration/60)+'分钟（非实时）':'未取得'],['距离',p=>p.distance!=null?(p.distance/1000).toFixed(1)+'km':'未取得'],['风险依据',p=>v5Risk(p)],['关联事件',p=>vRelated(p).map(e=>e.category).join('、')||'无明确匹配'],['返程',p=>p.roundTrip?.enabled?'需返回，停留'+p.roundTrip.stay+'分钟':'未设置']].map(([t,fn])=>`<tr><td>${t}</td>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">请选择至少两条方案。地图只显示勾选路径。</p>'}<button data-v5="report" data-value="方案比较">导出比较报告 ↗</button>`}
const v8EventsBase=vEventsPage;
vEventsPage=function(){return `<div class="v8eventpage">${v8EventsBase()}</div>`};
vAbout=function(){const body=v6AboutBase();return vHead('','关于与设置','个人资料、阅读偏好与项目说明。')+v5Personal()+body.slice(body.indexOf('<div class="panelgrid">'))};
vFeedbackPage=function(){const base=v5Base.feedback(),form=base.split('<section class="card"><h2>我的反馈与处理进度</h2>')[0],start=form.indexOf('<section class="card"><h2>提交反馈</h2>'),left=form.slice(start),rows=stored('sy-v2-feedback');return vHead('','用户反馈','提交现场事实，查看处理进度与回复。')+`<div class="v8feedbackgrid">${left}<section class="card"><div class="row"><h2>我的反馈</h2><span class="tag gray">${rows.length}条</span></div><div class="seg" style="margin:17px 0"><button data-v5="feedback-tab" data-value="progress" class="${V5.feedbackTab==='progress'?'active':''}">处理进度</button><button data-v5="feedback-tab" data-value="records" class="${V5.feedbackTab==='records'?'active':''}">反馈记录</button></div>${rows.length?rows.slice().reverse().map(f=>`<article class="v8feedbackitem"><div class="row"><b>${esc(f.place)}</b><span class="tag orange">${esc(f.status||'待核验')}</span></div><p>${esc(f.content)}</p><small>观察 ${esc(dateText(f.observed))}</small>${V5.feedbackTab==='progress'?v3FeedbackProgress(f):''}<div class="v8smallactions"><button data-v5="feedback-detail" data-value="${f.id}">查看记录与回复 ↗</button>${vPhoto(f)}<button data-v2="delete-feedback" data-value="${f.id}">删除</button></div></article>`).join(''):'<div class="v8empty"><div>'+icon('message',30)+'</div><b>你的观察，可以成为下一条线索。</b><p>提交后会在这里保留原始记录与处理进度。</p></div>'}<p class="muted" style="font-size:11px">反馈当前只保存在本浏览器；加急标记不表示已提交官方。</p><button data-v2="feedback-export">导出反馈摘要</button></section></div>`};
vRender();

const v8CommunityBase=v5Community;
v5Community=function(){return v8CommunityBase().replace(/<button data-v7="seed">[\s\S]*?<\/button>/,'')};
vRender();
